+
+.cta-donate{
+  background:var(--gold);
+  color:var(--navy);
+  box-shadow: 0 12px 26px rgba(254,172,50,.24);
+}
+.cta-donate:hover{filter:saturate(1.05);background: #ffb84d}
+
+.menu-btn{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:999px;border:1px solid var(--border);background:#fff;cursor:pointer}
+.menu-btn:hover{background:rgba(10,10,35,.04)}
+.menu-btn svg{width:20px;height:20px}
+@media (min-width: 860px){.menu-btn{display:none}}
+@media (max-width: 859px){.nav{display:none}}
+
+.mobile-nav{display:none;border-top:1px solid var(--border);padding:10px 0 14px}
+.mobile-nav[data-open="true"]{display:block}
+.mobile-nav a{display:block;padding:12px 10px;border-radius:12px;color:rgba(10,10,35,.90);font-weight:650}
+.mobile-nav a:hover{background:rgba(10,10,35,.04);text-decoration:none}
+
+/* Banner */
+.banner{
+  background: linear-gradient(90deg, rgba(254,172,50,.22), rgba(0,46,173,.10));
+  border-bottom:1px solid var(--border);
