+.banner a{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;color:var(--navy);text-decoration:none}
+.banner strong{font-weight:850;letter-spacing:-0.02em}
+.banner .pill{font-size:12px;font-weight:750;background:rgba(10,10,35,.08);padding:6px 10px;border-radius:999px}
+
+/* Page shell */
+main{padding:28px 0 64px}
+.page-title{font-size:clamp(28px, 4vw, 44px);line-height:1.08;letter-spacing:-0.04em;margin:0 0 10px}
+.page-subtitle{margin:0;color:var(--muted);max-width:72ch}
+
+/* Cards + grids */
+.grid{display:grid;grid-template-columns:1fr;gap:16px}
+@media (min-width: 780px){.grid{grid-template-columns:repeat(2, minmax(0, 1fr));gap:18px}}
+@media (min-width: 1100px){.grid{grid-template-columns:repeat(3, minmax(0, 1fr));gap:18px}}
+
+.card{
+  background: var(--surface);
+  border:1px solid var(--border);
+  border-radius: var(--radius);
+  overflow:hidden;
+  box-shadow: 0 1px 0 rgba(10,10,35,.03);
+  transition: transform 200ms ease, box-shadow 200ms ease, border-color 200ms ease;
+}
+.card:hover{transform: translateY(-2px);box-shadow: var(--shadow);border-color: oklch(0.87 0 0)}
+
+.thumb{aspect-ratio: 16/9;background: linear-gradient(135deg, rgba(10,10,35,.96), rgba(0,46,173,.40));position:relative}
+.thumb img{width:100%;height:100%;object-fit:cover;filter:saturate(1.05);opacity:.95}
+.tag{
+  position:absolute;left:12px;top:12px;
+  display:inline-flex;align-items:center;gap:8px;
+  background: rgba(10,10,35,.88);
+  color: #fff;
+  padding: 7px 10px;
+  border-radius: 999px;
+  font-weight: 800;
+  letter-spacing:.01em;
+  font-size: 12px;
+  box-shadow: 0 10px 18px rgba(10,10,35,.24);
+}
+.tag .dot{width:7px;height:7px;border-radius:999px;background: var(--gold)}
+
+.card-body{padding:14px 14px 16px}
+.card-title{margin:0 0 10px;font-size:18px;letter-spacing:-0.02em;line-height:1.25}
+.card-title a{color:var(--text);text-decoration:none}
+.card-title a:hover{text-decoration:underline}
+.meta{display:flex;align-items:center;justify-content:space-between;gap:10px;color:var(--muted);font-size:13px}
+.author{display:flex;align-items:center;gap:10px;min-width:0}
+.avatar{width:28px;height:28px;border-radius:999px;background:linear-gradient(180deg, rgba(254,172,50,.35), rgba(0,46,173,.18)), var(--navy);border:1px solid rgba(255,255,255,.65);box-shadow: 0 8px 14px rgba(10,10,35,.10)}
+.author-name{font-weight:700;color:rgba(10,10,35,.78);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
+
