+
+.featured-card{border-radius: 24px}
+.featured-card .thumb{aspect-ratio: 16/8}
+.featured-card .card-body{padding:18px}
+.featured-card .card-title{font-size:24px}
+@media (min-width: 980px){.featured-card .card-title{font-size:30px}}
+
+.side-panel{
+  background: linear-gradient(180deg, rgba(10,10,35,.92), rgba(10,10,35,.84));
+  border-radius: 24px;
+  color: rgba(255,255,255,.9);
+  padding: 18px;
+  border: 1px solid rgba(255,255,255,.10);
+  box-shadow: 0 22px 60px rgba(10,10,35,.20);
