+/* Buttons */
+.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;border-radius:999px;border:1px solid var(--border);padding:12px 16px;background:#fff;color:rgba(10,10,35,.9);font-weight:750;cursor:pointer;transition: transform 150ms ease, box-shadow 200ms ease, background 200ms ease, border-color 200ms ease}
