+@media (min-width: 900px){.syllabus{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}}
+
+.path{
+  background:var(--surface);
+  border:1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 14px;
+  display:flex;gap:12px;align-items:flex-start;
+}
+.path:hover{box-shadow: var(--shadow)}
+.icon{
+  width:40px;height:40px;border-radius:14px;
+  background: linear-gradient(135deg, rgba(254,172,50,.35), rgba(0,46,173,.12)), var(--navy);
+  display:grid;place-items:center;color:#fff;
+}
+.path h3{margin:0;font-size:16px;letter-spacing:-0.02em}
+.path p{margin:4px 0 0;color:var(--muted);font-size:13px}
+
+.two-col{display:grid;grid-template-columns:1fr;gap:16px}
+@media (min-width: 980px){.two-col{grid-template-columns: 1.1fr .9fr;gap:18px}}
+
+.panel{background:var(--surface);border:1px solid var(--border);border-radius: 24px;padding:18px;box-shadow: 0 1px 0 rgba(10,10,35,.03)}
+.panel h2{margin:0 0 8px}
+.panel p{margin:0 0 12px;color:var(--muted)}
+.list{margin:0;padding-left:18px;color:rgba(10,10,35,.84)}
+.list li{margin:7px 0}
+
+/* Donate */
+.donate-shell{display:grid;grid-template-columns:1fr;gap:16px;margin-top:14px}
+@media (min-width: 980px){.donate-shell{grid-template-columns: 1.1fr .9fr;gap:18px}}
+
+.donate-form{padding:18px}
+.amount-tabs{display:flex;gap:10px;flex-wrap:wrap;margin: 12px 0 10px}
+.tab{
+  padding:10px 14px;border-radius:999px;border:1px solid var(--border);
+  background: #fff;font-weight:850;cursor:pointer;min-width:74px;text-align:center;
+  transition: transform 150ms ease, box-shadow 200ms ease, background 200ms ease, border-color 200ms ease;
+}
+.tab:hover{background:rgba(10,10,35,.03)}
+.tab[aria-selected="true"]{background: rgba(254,172,50,.22);border-color: rgba(254,172,50,.55);box-shadow: 0 12px 26px rgba(254,172,50,.18)}
+.impact{margin:0 0 14px;color:rgba(10,10,35,.82)}
+.subtle{color:var(--muted);font-size:13px}
+
+.faq{margin-top:12px}
+.faq-item{border-top:1px solid var(--border)}
+.faq-button{width:100%;background:transparent;border:none;padding:14px 0;display:flex;align-items:center;justify-content:space-between;gap:12px;cursor:pointer;text-align:left;font-weight:800;color:rgba(10,10,35,.92)}
+.faq-button:focus{outline:none;box-shadow: 0 0 0 4px rgba(0,46,173,.12);border-radius: 12px}
+.faq-panel{max-height:0;overflow:hidden;transition:max-height 320ms ease;}
+.faq-panel-inner{padding:0 0 14px;color:var(--muted)}
+.chev{transition: transform 200ms ease}
+.faq-item[data-open="true"] .chev{transform: rotate(180deg)}
+.faq-item[data-open="true"] .faq-panel{max-height:220px}
+
+/* Tags */
+.tag-head{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:12px;margin-top:10px}
+.tag-head h1{margin:0}
+.tag-count{color:var(--muted);font-weight:700}
+
+.popular-tags{display:flex;gap:10px;overflow:auto;padding: 10px 2px 2px;margin: 12px 0 18px;scrollbar-width:thin}
+.chip{border:1px solid var(--border);background:#fff;border-radius:999px;padding:10px 12px;white-space:nowrap;display:flex;gap:10px;align-items:center}
+.chip strong{color:rgba(10,10,35,.86)}
+.chip span{color:var(--muted);font-weight:750}
+
+/* Footer */
+.site-footer{border-top:1px solid var(--border);padding:28px 0 34px;background: rgba(255,255,255,.7)}
+.footer-grid{display:grid;grid-template-columns:1fr;gap:18px}
+@media (min-width: 980px){.footer-grid{grid-template-columns: 1.2fr .8fr}}
+.mission{color:rgba(10,10,35,.78);max-width:80ch}
+.footer-links{display:flex;flex-wrap:wrap;gap:10px}
+.footer-links a{color:rgba(10,10,35,.72);font-weight:650}
+.kicker{font-size:12px;color:var(--muted);margin-top:12px}
+
+/* Utility */
+.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
+
*** End Patch
PATCH

